function rankWord(w){const n=w.en.length;if(w.type==='basic')return n<=5?'elementary':n<=7?'middle':'high';if(['root','irregular'].includes(w.type))return'advanced';if(w.type==='phrase')return n<=8?'high':n<=10?'intermediate':'advanced';if(['prefix','suffix'].includes(w.type))return n<=5?'high':'intermediate';return n<=5?'middle':n<=7?'high':n<=9?'intermediate':'advanced'}
const WORDS=[...BASE_WORDS,...EXTRA_WORDS].map((w,i)=>({...w,id:i,answers:w.answers||w.ko.split('|'),difficulty:rankWord(w)}));
const EASY_WORDS=WORDS.filter(w=>w.difficulty==='elementary');
const DIFFICULTY={elementary:{label:'초등',speed:24,interval:2.55},middle:{label:'중등',speed:28,interval:2.35},high:{label:'고등',speed:32,interval:2.15},intermediate:{label:'중급',speed:37,interval:1.95},advanced:{label:'고급',speed:42,interval:1.75}};
const TYPE_LABEL={basic:'기본',noun:'명사',verb:'동사',adj:'형용사',adv:'부사',phrase:'표현',prefix:'접두사',suffix:'접미사',root:'어근',irregular:'불규칙'};

const $=s=>document.querySelector(s);const screens=['startScreen','gameScreen','resultScreen'];
const els={start:$('#startBtn'),retry:$('#retryBtn'),save:$('#saveImageBtn'),home:$('#homeBtn'),pause:$('#pauseBtn'),resume:$('#resumeBtn'),quit:$('#quitBtn'),modal:$('#pauseModal'),field:$('#playfield'),layer:$('#wordLayer'),form:$('#answerForm'),input:$('#answer'),score:$('#score'),combo:$('#combo'),level:$('#level'),levelGauge:$('#levelGauge'),gaugeValue:$('#gaugeValue'),feedback:$('#feedback'),comboBurst:$('#comboBurst'),levelUp:$('#levelUp'),resultBadge:$('#resultBadge')};
let state,raf,lastTime,spawnClock,selectedMode='elementary';
function show(id){screens.forEach(x=>$('#'+x).classList.toggle('active',x===id))}
function getPool(){return WORDS.filter(w=>w.difficulty===selectedMode)}
function reset(){const pool=getPool();state={score:0,combo:0,maxCombo:0,correct:0,missed:[],active:[],pool,deck:[...pool].sort(()=>Math.random()-.5),running:true,paused:false,ending:false,elapsed:0,level:1,pressure:0,lastCorrectAt:0,groundRise:0};els.layer.innerHTML='';els.field.classList.remove('hit','ground-impact','deadline-hit');els.field.style.setProperty('--ground-rise','0px');spawnClock=0;lastTime=performance.now();updateHud()}
function start(){reset();show('gameScreen');spawn();els.input.value='';setTimeout(()=>els.input.focus(),120);cancelAnimationFrame(raf);raf=requestAnimationFrame(loop)}
function spawn(){if(!state.deck.length)state.deck=[...state.pool].sort(()=>Math.random()-.5);const word=state.deck.pop(),node=document.createElement('div');node.className='word';node.textContent=word.en;els.layer.appendChild(node);const maxX=Math.max(8,els.field.clientWidth-node.offsetWidth-8),base=DIFFICULTY[selectedMode].speed;const item={...word,node,x:8+Math.random()*maxX,y:-52,speed:base+Math.random()*7};state.active.push(item);node.style.transform=`translate(${item.x}px,${item.y}px)`}
function showLevelUp(){els.levelUp.querySelector('span').textContent=state.level;els.levelUp.classList.remove('show');void els.levelUp.offsetWidth;els.levelUp.classList.add('show');navigator.vibrate?.([25,35,55])}
function addPressure(amount){if(!state?.running||state.ending)return;state.pressure=Math.max(0,state.pressure+amount);while(state.pressure>=100&&state.level<7){state.pressure-=100;state.level++;const deadlineTop=96,maxRise=Math.max(0,els.field.clientHeight-62-deadlineTop);state.groundRise=Math.round(maxRise*((state.level-1)/6));els.field.style.setProperty('--ground-rise',state.groundRise+'px');els.field.classList.remove('ground-impact');void els.field.offsetWidth;els.field.classList.add('ground-impact');showLevelUp();if(state.level>=7){state.ending=true;els.field.classList.add('deadline-hit');flash('DEAD LINE!','#ff5171');navigator.vibrate?.([70,35,70,35,120]);setTimeout(end,850);break}}updateGauge()}
function updateGauge(){const value=Math.round(Math.max(0,Math.min(100,state.pressure)));els.levelGauge.style.transform=`scaleX(${value/100})`;els.gaugeValue.textContent=value+'%';els.levelGauge.classList.toggle('hot',value>=72)}
function loop(now){if(!state?.running)return;const dt=Math.min((now-lastTime)/1000,.05);lastTime=now;if(!state.paused&&!state.ending){state.elapsed+=dt;spawnClock+=dt;const drought=Math.max(0,state.elapsed-state.lastCorrectAt);addPressure(dt*(1.15+Math.min(3.1,drought*.11)+state.active.length*.12));const interval=DIFFICULTY[selectedMode].interval,cap=5;if(spawnClock>=interval&&state.active.length<cap){spawnClock=0;spawn()}const limit=els.field.clientHeight-110-state.groundRise;for(let i=state.active.length-1;i>=0;i--){const w=state.active[i];w.y+=w.speed*dt;w.node.style.transform=`translate(${w.x}px,${w.y}px)`;w.node.classList.toggle('danger',w.y>=limit-95);if(w.y>=limit)miss(i)}}raf=requestAnimationFrame(loop)}
function norm(v){return v.trim().replace(/\s+/g,'').replace(/[.!?]/g,'')}
function answer(e){e.preventDefault();if(!state?.running||state.paused||state.ending)return;const value=norm(els.input.value);if(!value)return;let idx=state.active.findIndex(w=>w.answers.some(a=>norm(a)===value));if(idx<0){state.combo=0;addPressure(9);flash('위험 +9','#ef5b61');navigator.vibrate?.(40)}else{const w=state.active[idx];state.active.splice(idx,1);w.node.classList.add('correct-pop');setTimeout(()=>w.node.remove(),190);state.combo++;state.maxCombo=Math.max(state.maxCombo,state.combo);state.correct++;state.lastCorrectAt=state.elapsed;state.pressure=Math.max(0,state.pressure-(28+Math.min(12,state.combo*2)));updateGauge();const mult=1+(state.level-1)*.25,gain=Math.round((100+Math.min(400,(state.combo-1)*20))*mult);state.score+=gain;els.field.classList.remove('hit');void els.field.offsetWidth;els.field.classList.add('hit');els.comboBurst.textContent=state.combo>1?`${state.combo} COMBO!`:`+${gain}`;els.comboBurst.classList.remove('show');void els.comboBurst.offsetWidth;els.comboBurst.classList.add('show');flash(`위험 DOWN · +${gain}`,'#57d7d9');navigator.vibrate?.(state.combo>=5?[18,22,28]:18)}els.input.value='';updateHud()}
function miss(i){const [w]=state.active.splice(i,1);w.node.remove();state.missed.push(w);state.combo=0;addPressure(34);flash(`${w.en} = ${w.answers[0]} · 위험 UP`,'#ef5b61');navigator.vibrate?.([40,30,40]);updateHud()}
function flash(text,color){els.feedback.textContent=text;els.feedback.style.color=color;els.feedback.classList.remove('show');void els.feedback.offsetWidth;els.feedback.classList.add('show')}
function updateHud(){els.score.textContent=state.score.toLocaleString();els.combo.textContent=state.combo;els.level.textContent=state.level;updateGauge()}
function pause(){if(!state?.running)return;state.paused=true;els.modal.classList.add('open');els.input.blur()}
function resume(){state.paused=false;lastTime=performance.now();els.modal.classList.remove('open');els.input.focus()}
function end(){if(!state?.running)return;state.running=false;cancelAnimationFrame(raf);els.modal.classList.remove('open');const best=Math.max(Number(localStorage.getItem('wordRainBest')||0),state.score);localStorage.setItem('wordRainBest',best);$('#finalScore').textContent=state.score.toLocaleString();$('#correctCount').textContent=state.correct;$('#maxCombo').textContent=state.maxCombo;$('#missCount').textContent=state.missed.length;$('#bestStart').textContent=best.toLocaleString();els.resultBadge.textContent=`${DIFFICULTY[selectedMode].label} · LEVEL ${state.level}`;const unique=[...new Map(state.missed.map(w=>[w.en,w])).values()];state.reviewWords=unique;$('#review').innerHTML=unique.length?'<p style="background:transparent;font-weight:900">틀린 단어 전체 복습</p>'+unique.map(w=>`<p><b>${w.en}</b> &nbsp; ${w.answers.join(', ')}</p>`).join(''):'<p>놓친 단어가 없어요. 완벽해요! 🎉</p>';els.save.textContent='결과 이미지 저장 ↓';show('resultScreen')}
function roundRect(ctx,x,y,w,h,r,fill){ctx.beginPath();if(ctx.roundRect)ctx.roundRect(x,y,w,h,r);else ctx.rect(x,y,w,h);ctx.fillStyle=fill;ctx.fill()}
async function saveResultImage(){if(!state)return;const words=state.reviewWords||[];const width=1080,height=Math.max(1180,890+words.length*94);const c=document.createElement('canvas');c.width=width;c.height=height;const x=c.getContext('2d'),g=x.createLinearGradient(0,0,width,height);g.addColorStop(0,'#fff7e8');g.addColorStop(1,'#dff3eb');x.fillStyle=g;x.fillRect(0,0,width,height);x.textAlign='center';x.fillStyle='#ff7557';x.font='900 34px system-ui,sans-serif';x.fillText('하루 3분, 손끝으로 외우기',540,100);x.fillStyle='#17324d';x.font='1000 92px system-ui,sans-serif';x.fillText('단어비',540,215);roundRect(x,140,280,800,250,54,'#ffffff');x.fillStyle='#82909b';x.font='800 28px system-ui,sans-serif';x.fillText('TODAY SCORE',540,350);x.fillStyle='#17324d';x.font='1000 112px system-ui,sans-serif';x.fillText(state.score.toLocaleString(),540,475);[['맞힌 단어',state.correct],['최고 콤보',state.maxCombo],['놓친 단어',state.missed.length]].forEach(([label,value],i)=>{const cx=270+i*270;x.fillStyle='#82909b';x.font='700 25px system-ui,sans-serif';x.fillText(label,cx,610);x.fillStyle=i===2?'#ef5b61':'#17324d';x.font='1000 52px system-ui,sans-serif';x.fillText(value,cx,675)});x.textAlign='left';x.fillStyle='#17324d';x.font='1000 38px system-ui,sans-serif';x.fillText(words.length?'틀린 단어 복습':'완벽해요!',110,770);if(words.length){words.forEach((w,i)=>{const y=810+i*94;roundRect(x,95,y,890,74,22,'#ffffff');x.fillStyle='#ff7557';x.font='900 31px system-ui,sans-serif';x.fillText(w.en,130,y+48);x.fillStyle='#536677';x.font='700 29px system-ui,sans-serif';x.fillText(w.answers.join(', '),500,y+48)})}else{x.textAlign='center';x.fillStyle='#536677';x.font='700 31px system-ui,sans-serif';x.fillText('놓친 단어가 하나도 없어요!',540,860)}x.textAlign='center';x.fillStyle='#82909b';x.font='700 23px system-ui,sans-serif';x.fillText('WORD RAIN · 나의 영단어 기록',540,height-55);const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));const file=new File([blob],`단어비-결과-${new Date().toISOString().slice(0,10)}.png`,{type:'image/png'});try{if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'단어비 학습 결과'})}else{const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}els.save.textContent='저장 완료 ✓'}catch(e){if(e.name!=='AbortError')els.save.textContent='다시 저장하기'}}
els.start.onclick=start;els.retry.onclick=start;els.save.onclick=saveResultImage;els.home.onclick=()=>{show('startScreen');$('#bestStart').textContent=Number(localStorage.getItem('wordRainBest')||0).toLocaleString()};els.pause.onclick=pause;els.resume.onclick=resume;els.quit.onclick=end;els.form.onsubmit=answer;document.addEventListener('visibilitychange',()=>{if(document.hidden&&state?.running&&!state.paused)pause()});$('#bestStart').textContent=Number(localStorage.getItem('wordRainBest')||0).toLocaleString();
function syncViewport(){const h=Math.round(window.visualViewport?.height||window.innerHeight);document.documentElement.style.setProperty('--app-height',`${h}px`)}
window.visualViewport?.addEventListener('resize',syncViewport);window.visualViewport?.addEventListener('scroll',syncViewport);window.addEventListener('resize',syncViewport);syncViewport();
$('#vocabCount').textContent=getPool().length;document.querySelectorAll('.mode-chip').forEach(btn=>btn.onclick=()=>{selectedMode=btn.dataset.mode;document.querySelectorAll('.mode-chip').forEach(b=>b.classList.toggle('active',b===btn));$('#vocabCount').textContent=getPool().length});
